INSERT INTO T_BROADCAST_MSG (
	B_MSG_KEY, LOGIN_ID, USER_ID, TITLE, MSG, IN_TIME,	CALLBACK_NO, REQ_TIME, CNT, SUCC_CNT, FAIL_CNT, STATUS, SVC_TYPE, SEND_INFO
) VALUES(
	#{bMsgKey}, #{loginId}, #{userId}, #{title}, CAST(#{msg} AS VARCHAR(2000)), GETDATE(), #{callbackNo}, #{regTime}, #{cnt}, #{succCnt}, #{failCnt}, #{status}, #{svcType}, #{sendInfo}
)
